    .replace(/[\\<>&@!|#*_[\]()`~]/g, (letter) => "\\" + letter);
}

function reportPlan(pages, comparisons, settings, time) {
  if (
    pages.length !== comparisons.length ||
    comparisons.some((item, index) => item.url !== pages[index].url || !Array.isArray(item.changes))
  ) {
    throw new Error("Cannot associate every comparison with its original page.");
  }
  const included = comparisons.filter((item) => item.changes.length);
  const clock = new Date(time);
  if (!Number.isFinite(clock.valueOf())) throw new Error("Missing schedule timestamp.");
  clock.setUTCDate(clock.getUTCDate() - ((clock.getUTCDay() + 6) % 7));
  const period = clock.toISOString().slice(0, 10);
  const title = "Visual Regression Report " + period;
  const description = included
    .map(
      (page) =>
        "### " +
        escapeReport(page.url) +
        "\n" +
        page.changes
          .map(
            (change) =>
              "- **" +
              escapeReport(change.description) +
              "** (" +
              change.type +
              "): “" +
              escapeReport(change.previous_state) +
              "” → “" +
              escapeReport(change.current_state) +
              "”",
          )
          .join("\n"),
    )
    .join("\n\n");
  return {
    required: included.length > 0,
    teamId: settings.destinationId,
    title,
    description: "Review these AI-detected differences against the screenshots.\n\n" + description,
    fingerprint: JSON.stringify([
      "visual-regression",
      settings.sheetId,
      settings.tab,
      settings.destinationId,
      period,
    ]),
  };
}

function reportId(hex) {
  if (!/^[a-f0-9]{64}$/.test(hex)) throw new Error("Missing report fingerprint.");
  return (
    hex.slice(0, 8) +
    "-" +
    hex.slice(8, 12) +
    "-4" +
    hex.slice(13, 16) +
    "-8" +
    hex.slice(17, 20) +
    "-" +
    hex.slice(20, 32)
  );
}

export default ({ pages, comparisons, config, time }) => {
  const plan = reportPlan(pages, comparisons, config, time);
  return { plan, id: reportId(sha(plan.fingerprint)), required: plan.required, title: plan.title };
};

